import {hasValue,number,selectGames,rankGenres,summarizeGenreTags,GENRE_TAG_METHOD,POPULARITY_SCORE_METHOD,escapeHtml as e,safeUrl} from './model.js';
let data;let genreRanks=[];const app=document.querySelector('#app');
const icon={
 overview:'<svg viewBox="0 0 24 24"><rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/></svg>',
 search:'<svg viewBox="0 0 24 24"><circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/></svg>',
 marketing:'<svg viewBox="0 0 24 24"><path d="M4 9v6h4l10 4V5L8 9H4Zm4 6 2 6h3l-2-5M21 9v6"/></svg>',
 methods:'<svg viewBox="0 0 24 24"><ellipse cx="12" cy="5" rx="8" ry="3"/><path d="M4 5v14c0 4 16 4 16 0V5M4 12c0 4 16 4 16 0"/></svg>'
};
const genreArt=[
 '<path d="M14 41h36M18 41V27l14-12 14 12v14M26 41V30h12v11M32 15V8M27 11h10"/>',
 '<path d="m15 39 10-19 10 19M19 32h13M39 42V26M35 30l4-7 7 6M12 47h40"/>',
 '<path d="M32 47V20M32 35C17 35 12 27 14 18c12-1 18 5 18 17ZM32 29c13 0 19-8 18-17-12 0-18 6-18 17ZM19 47h26"/>',
 '<path d="m32 10 21 38H11l21-38ZM32 21v12M32 39v2"/><circle cx="32" cy="32" r="25" opacity=".3"/>',
 '<path d="M10 44h12V33h13V22h17M15 18l6-5 6 5-6 5-6-5Z"/>',
 '<path d="M12 12h15v8c7-4 12-1 12 4s-5 8-12 4v10H12V12ZM37 38v14h15V27h-9"/>',
 '<path d="m17 14 21-4 9 35-21 5-9-36ZM10 20l-2 5 9 27 5-2M31 23l7 6-3 9-7-6 3-9Z"/>'
];
const genreIcon=genre=>`<svg viewBox="0 0 64 64" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${genreArt[data.genres.indexOf(genre)]||genreArt[0]}</svg>`;
const shortGenre=genre=>({'Farming / life simulation':'Farming & life sim','Roguelike deckbuilder':'Roguelike deckbuilder','Horror / exploration':'Horror & exploration','Platformer / metroidvania':'Platformer & metroidvania','Colony / settlement simulation':'Colony & settlement sim'})[genre]||genre;
const readable=s=>String(s||'Unknown').replaceAll('_',' ');
const date=s=>s?new Date(s).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric',timeZone:'UTC'}):'Undated';
const summaryNumber=value=>value.toLocaleString('en-US',{maximumFractionDigits:1});
const scoreNumber=value=>value.toFixed(1);
const stamp=s=>s?new Date(s).toLocaleString('en-GB',{timeZone:'UTC',hour12:false})+' UTC':'Not captured';
const link=(url,label,cls='source')=>safeUrl(url)?`<a class="${cls}" href="${e(safeUrl(url))}" target="_blank" rel="noopener noreferrer">${e(label)} <span aria-hidden="true">→</span></a>`:'';
const route=(path,params={})=>'#/'+path+(Object.values(params).some(Boolean)?'?'+new URLSearchParams(Object.entries(params).filter(([,v])=>v)).toString():'');
const state=()=>{const u=new URL((location.hash.slice(1)||'/overview'),'https://local.test');return {path:u.pathname.split('/').filter(Boolean),params:Object.fromEntries(u.searchParams)}};
const pill=(text,kind='')=>`<span class="pill ${kind}">${e(text)}</span>`;
const eyebrow=t=>`<div class="eyebrow">${t}</div>`;
const title=(small,heading,description,extra='')=>`<header class="page-heading"><div>${eyebrow(small)}<h1>${e(heading)}</h1><p>${e(description)}</p></div>${extra}</header>`;
const sourceTags=games=>{const counts=new Map();games.forEach(g=>new Set((g.tags||[]).filter(t=>typeof t==='string'&&t.trim())).forEach(t=>counts.set(t,(counts.get(t)||0)+1)));return [...counts].sort((a,b)=>b[1]-a[1]||a[0].localeCompare(b[0]))};
const metricFreshness=metric=>metric?.freshness==='stale_cache'?'Stale cache':metric?.freshness==='accepted_run'?'Saved run':metric?.refresh?'Not captured':'';
const metricNote=metric=>metric?.refresh?`<small class="metric-freshness">${e(metricFreshness(metric))} · ${e(date(metric.observedAt))}${metric.refresh.status!=='accepted'?' · '+e(readable(metric.refresh.status)):''}</small>`:'';
const windowText=(start,end)=>{if(!start)return 'Not captured';if(!end||start===end)return stamp(start);const time=value=>new Date(value).toLocaleTimeString('en-GB',{timeZone:'UTC',hour12:false});return date(start)===date(end)?`${date(start)}, ${time(start)}–${time(end)} UTC`:`${stamp(start)} – ${stamp(end)}`;};
const rankWindow=()=>{const times=genreRanks.flatMap(row=>[row.observedStart,row.observedEnd]).filter(Boolean).sort((a,b)=>Date.parse(a)-Date.parse(b));return {start:times[0]||null,end:times.at(-1)||null};};
const metricWindow=()=>{const times=data.games.flatMap(g=>[g.players.observedAt,g.reviews.observedAt]).filter(Boolean).sort((a,b)=>Date.parse(a)-Date.parse(b));return {start:times[0]||null,end:times.at(-1)||null};};
const steamStatusText=()=>data.meta.steamMetricsIntegration?.status==='imported'?`A bounded saved Steam run supplies ${data.meta.steamMetricsIntegration.accepted.players} accepted player counts and ${data.meta.steamMetricsIntegration.accepted.reviews} accepted all-time review totals. Any retained older values are marked stale cache and excluded from the run’s Popularity Scores. IGDB catalog and saved tag dates remain separate. The browser makes no live source requests.`:'Steam metrics remain the preserved pilot observations after the earlier proxy 403 refusal. IGDB catalog coverage is reported separately below. This prototype only reads local saved evidence and does not refresh either source.';
function shell(page,content){const label={overview:'Overview',search:'Search',marketing:'Marketing info',methods:'Data, sources & methods'}[page]||'Research';return `<aside class="sidebar"><a href="#/overview" class="brand" aria-label="Fieldnote home"><span class="brand-mark" aria-hidden="true"><svg viewBox="0 0 32 32"><path d="M7 25V7h20l-4 5H13v4h10l-4 5h-6v4Z" fill="currentColor"/></svg></span><span>fieldnote<small>GAME INTELLIGENCE</small></span></a><div class="workspace-label">WORKSPACE <span>01</span></div><nav aria-label="Main navigation">${[['overview','Overview'],['search','Search'],['marketing','Marketing info'],['methods','Data / sources / methods']].map(([id,label])=>`<a href="#/${id}" class="nav-link ${page===id?'active':''}" ${page===id?'aria-current="page"':''}><span aria-hidden="true">${icon[id]}</span>${label}${page===id?'<i aria-hidden="true"></i>':''}</a>`).join('')}</nav><div class="sidebar-bottom"><div class="sidebar-grid" aria-hidden="true"><span>F / N</span></div><span class="status-dot"></span> LOCAL WORKSPACE<p>Explore the signal.<br>Understand the source.</p><a href="#/methods">About the data <span>→</span></a></div></aside><div class="workspace"><div class="topbar"><span>Workspace <span class="slash">/</span> <b>${label}</b></span><div class="platforms"><span class="selected"><span class="platform-icon" aria-hidden="true">▣</span> PC / STEAM</span><span class="snapshot-status">SNAPSHOT MODE</span></div></div><main id="main" tabindex="-1">${content}</main><footer><span>FIELDNOTE <b>/</b> GAME INTELLIGENCE</span><span>Investigate. Compare. Find your next move.</span></footer></div>`;}
function genreSearch(params={},full=false){const query=params.genreQuery||'';const matches=data.genres.filter(g=>g.toLowerCase().includes(query.trim().toLowerCase()));return `<section class="genre-search-panel panel" aria-labelledby="genre-search-heading"><div class="search-card-heading"><div><div class="eyebrow">EXPLORE YOUR NEXT IDEA</div><h2 id="genre-search-heading">Search a genre<span class="accent">.</span></h2></div><span class="search-decor" aria-hidden="true">${icon.search}</span></div><form id="genre-form" class="genre-form" role="search" aria-label="Genre search"><div class="search-wrap"><span aria-hidden="true">${icon.search}</span><input id="genre-search" name="genreQuery" type="search" placeholder="Try puzzle, farming, roguelike…" aria-label="Search genres" value="${e(query)}" autocomplete="off"><kbd>/</kbd></div><button class="button" type="submit">Explore genres <span aria-hidden="true">→</span></button></form><div class="genre-search-meta"><span>${query?`${matches.length} ${matches.length===1?'matching genre':'matching genres'}`:'Browse a genre to explore its games'}</span>${query?'<button class="text-button" data-clear-genre>Clear search</button>':`<span>${full?'SOURCE-DEFINED GENRES':'FIND YOUR FOCUS'}</span>`}</div><div class="genre-results" aria-live="polite">${matches.length?matches.map(genre=>`<a class="genre-result" href="${route('genre/'+encodeURIComponent(genre))}" title="${e(genre)}"><span>${e(shortGenre(genre))}</span><span aria-hidden="true">→</span></a>`).join(''):'<div class="genre-empty"><b>No matching genres</b><p>Try a broader term like “puzzle” or clear your search.</p></div>'}</div></section>`;}
function overview(params){
 const ranked=genreRanks;
 const rows=ranked.filter(row=>row.observedCount>0);
 const leaders=rows.slice(0,5);
 const dates=rows.flatMap(row=>[row.observedStart,row.observedEnd]).sort((a,b)=>Date.parse(a)-Date.parse(b));
 const observedDate=dates.length?date(dates[0]):'Date unavailable';
 const formatTime=value=>new Date(value).toLocaleTimeString('en-GB',{hour:'2-digit',minute:'2-digit',timeZone:'UTC'});
 return title('THE GAMING LANDSCAPE','Find your next move.','Explore player activity. Discover genres. Follow the evidence.',`<div class="heading-id"><span class="status-dot"></span> INTELLIGENCE / 01</div>`)+`<section class="ranking-section" aria-labelledby="ranking-heading"><div class="section-heading"><div><div class="eyebrow">GENRE LEADERBOARD</div><h2 id="ranking-heading">Top 5 genres<span class="accent">.</span></h2></div><div class="ranking-context"><span class="mini-bars" aria-hidden="true"><i></i><i></i><i></i></span><span>By Popularity Score<small>Provisional · Relative score</small></span></div></div><div class="ranking-grid">${leaders.map((row,i)=>`<a class="ranking-card rank-${i+1}" href="${route('genre/'+encodeURIComponent(row.genre))}" aria-label="Rank ${i+1}: ${e(row.genre)}, Popularity Score ${scoreNumber(row.popularityScore)} out of 100, average ${summaryNumber(row.average)} concurrent players per game, median ${summaryNumber(row.median)}, ${row.observedCount} observed ${row.observedCount===1?'game':'games'}"><div class="rank-top"><span class="rank-number">${String(i+1).padStart(2,'0')}</span><span class="rank-arrow" aria-hidden="true">→</span></div><div class="rank-art">${genreIcon(row.genre)}</div><h3>${e(shortGenre(row.genre))}</h3><div class="rank-value">${scoreNumber(row.popularityScore)}<small> / 100</small></div><div class="rank-label">Popularity Score</div><div class="rank-comparison"><span>Average <b>${summaryNumber(row.average)}</b></span><span>Median <b>${summaryNumber(row.median)}</b></span><span class="rank-observations">${row.observedCount} observed ${row.observedCount===1?'game':'games'}</span></div><div class="rank-meter" aria-hidden="true"><span style="width:${row.popularityScore}%"></span></div></a>`).join('')}${leaders.length<5?`<div class="ranking-card rank-unavailable"><div class="rank-top"><span class="rank-number">05</span>${pill('UNRANKED','neutral')}</div><div class="rank-art unavailable-art" aria-hidden="true"><span>?</span></div><h3>Fifth rank unavailable</h3><div class="unavailable-value">Not captured</div><p>No supported player observations for a fifth genre.</p><a class="text-link" href="#/methods">View coverage <span>→</span></a></div>`:''}</div><div class="ranking-footnote"><span><span class="info-dot" aria-hidden="true">i</span> ${dates.length?e(windowText(dates[0],dates.at(-1))):e(observedDate)} · Small-sample, relative engagement proxy. 100 = strongest measured genre in this snapshot. Not live or market-wide.</span><a href="#/methods">Methodology →</a></div></section>${genreSearch(params)}`;
}
function controls(params,lockedGenre){return `<div class="filter-bar"><div class="search-wrap"><span aria-hidden="true">⌕</span><input id="search" aria-label="Search games or source tags" type="search" placeholder="Search games or source tags…" value="${e(params.query||'')}" autocomplete="off"><kbd>/</kbd></div>${lockedGenre?'':`<label class="select-wrap"><span>Genre</span><select data-filter="genre" aria-label="Filter by genre"><option value="">All genres</option>${data.genres.map(g=>`<option ${params.genre===g?'selected':''}>${e(g)}</option>`).join('')}</select></label>`}<label class="select-wrap"><span>Cohort</span><select data-filter="cohort" aria-label="Filter by cohort"><option value="">All 36 games</option><option value="original_30" ${params.cohort==='original_30'?'selected':''}>Original 30</option><option value="recent_6" ${params.cohort==='recent_6'?'selected':''}>Recent supplement · 6</option></select></label><label class="select-wrap"><span>Sort</span><select data-filter="sort" aria-label="Sort games"><option value="players" ${(!params.sort||params.sort==='players')?'selected':''}>Players · high to low</option><option value="reviews" ${params.sort==='reviews'?'selected':''}>Reviews · high to low</option><option value="name" ${params.sort==='name'?'selected':''}>Name · A to Z</option></select></label></div>`;}
function gameTable(games){if(!games.length)return `<div class="empty"><span>⌕</span><h2>No games found</h2><p>Try another name or source tag, or clear the filters.</p><button class="button" data-reset>Clear filters</button></div>`;return `<div class="swipe-hint">Scroll the table sideways to see all metrics →</div><div class="table-scroll" tabindex="0" role="region" aria-label="Game comparison table, scroll horizontally for more metrics"><table><thead><tr><th>Game / source tags</th><th>Research genre</th><th class="numeric">Concurrent players <small>Observed snapshot</small></th><th class="numeric">API review total <small>All-language · Steam purchases</small></th><th>Marketing source</th></tr></thead><tbody>${games.map(g=>`<tr><td><a href="${route('game/'+g.id)}" class="game-name"><span class="game-avatar color-${data.genres.indexOf(g.genre)%4}">${e(g.name.slice(0,1))}</span><span>${e(g.name)}<small>${e(g.tags.slice(0,3).join(' · '))}</small></span></a></td><td><a class="genre-link" href="${route('genre/'+encodeURIComponent(g.genre))}">${e(g.genre)}</a>${g.cohort==='recent_6'?'<small class="recent">Recent supplement</small>':''}</td><td class="numeric ${hasValue(g.players)?'':'missing'}">${number(g.players)}${metricNote(g.players)}</td><td class="numeric ${hasValue(g.reviews)?'':'missing'}">${number(g.reviews)}${metricNote(g.reviews)}</td><td>${pill(g.marketing.deepProof?'Deep evidence':readable(g.marketing.status),g.marketing.deepProof?'green':g.marketing.status==='readable'?'':'neutral')}</td></tr>`).join('')}</tbody></table></div>`;}
function genreSummary(genre,params={}) {
 const row=genreRanks.find(row=>row.genre===genre);
 if(!row)return '';
 const patterns=summarizeGenreTags(data.games,genre);
 const tags=sourceTags(data.games.filter(game=>game.genre===genre));
 const observedCoverage=row.gameCount?100*row.observedCount/row.gameCount:0;
 const rawStat=value=>value===null?'Not captured':summaryNumber(value);
 const observationWindow=row.observedStart?`${stamp(row.observedStart)} – ${stamp(row.observedEnd)}`:'Not captured';
 const sparseNote=patterns.tags.length&&patterns.tags.length<5?`Only ${patterns.tags.length} recurring ${patterns.tags.length===1?'tag meets':'tags meet'} the rule; showing all ${patterns.tags.length}.`:'';
 const emptyNote=!patterns.taggedGameCount?'No saved Steam tags are available for this genre.':patterns.taggedGameCount<2?'Need at least two games sharing a classified tag. This genre has only one game with saved tags.':'No classified mechanic or theme tag appears in at least two games in this saved sample.';
 return `<section class="genre-summary" data-genre="${e(genre)}" aria-labelledby="genre-summary-heading"><div class="section-heading"><div><div class="eyebrow">GENRE SAMPLE</div><h2 id="genre-summary-heading">${e(shortGenre(genre))}<span class="accent">.</span></h2></div><a class="summary-method-link" href="#/methods">How this is measured →</a></div>
 <div class="genre-summary-grid"><div class="panel genre-score-card"><div class="genre-score-heading"><h3>Popularity Score</h3>${row.popularityScore===null?pill('UNRANKED','neutral'):pill('HEURISTIC v'+POPULARITY_SCORE_METHOD.version,'green')}</div><div class="genre-score ${row.popularityScore===null?'unavailable':''}" data-metric="popularity-score">${row.popularityScore===null?'Not captured':`${scoreNumber(row.popularityScore)}<small> / 100</small>`}</div><p class="genre-score-caption">Provisional · Relative score</p><dl class="genre-statistics"><div><dt>Mean players / game</dt><dd data-metric="mean">${rawStat(row.average)}</dd></div><div><dt>Median players / game</dt><dd data-metric="median">${rawStat(row.median)}</dd></div></dl><div class="genre-observed"><span><strong data-metric="observed-games">${row.observedCount} / ${row.gameCount}</strong> observed games</span><span>${summaryNumber(observedCoverage)}% coverage</span></div><div class="summary-meter" aria-hidden="true"><span style="width:${observedCoverage}%"></span></div><p class="genre-score-note">Global snapshot baseline. 100 = strongest measured genre. Small, selected sample; no uncertainty adjustment.</p></div>
 <div class="panel genre-pattern-card"><div class="genre-pattern-heading"><div><div class="eyebrow">SAVED STEAM TAGS</div><h3>Top 5 recurring mechanics &amp; themes</h3></div><span class="pattern-count">${patterns.tags.length} / 5</span></div><p class="genre-pattern-description">${patterns.taggedGameCount} / ${patterns.gameCount} ${patterns.gameCount===1?'game has':'games have'} saved tags. Each percentage uses ${patterns.taggedGameCount===1?'the':'all'} ${patterns.taggedGameCount} tagged ${patterns.taggedGameCount===1?'game':'games'} in this genre.</p>${patterns.tags.length?`<ol class="trait-list">${patterns.tags.map(item=>`<li><button class="trait-button ${params.tag===item.tag?'chosen':''}" data-tag="${e(item.tag)}" aria-pressed="${params.tag===item.tag}" title="Filter games by Steam tag: ${e(item.tag)}"><span class="trait-main"><span class="trait-name">${e(item.tag)}</span><span class="trait-type ${item.type}">${item.type==='mechanic'?'Mechanic':'Theme'}</span></span><span class="trait-frequency"><strong>${item.count} / ${patterns.taggedGameCount} games</strong><span>${summaryNumber(item.percentage)}%</span></span><span class="trait-meter" aria-hidden="true"><span style="width:${item.percentage}%"></span></span></button></li>`).join('')}</ol>`:`<div class="genre-pattern-empty"><h4>No recurring patterns captured</h4><p>${emptyNote}</p></div>`}${sparseNote?`<p class="pattern-sparse">${sparseNote}</p>`:''}<p class="genre-pattern-note">At least two games per tag. Source-tag proxies, classified by a conservative heuristic; not validated game features. Click a tag to filter the games below.</p></div></div>
 <div class="genre-summary-context"><p><b>Player observations:</b> ${e(observationWindow)}</p><p><b>Source snapshot:</b> collected through ${e(stamp(data.meta.collectionWindow.end))} · built ${e(stamp(data.meta.builtAt))}</p><p><b>Saved Steam tag window:</b> ${e(windowText(data.meta.tagCollectionWindow?.start,data.meta.tagCollectionWindow?.end))}. Tag evidence is separate from the player run.</p><p>Metrics and tag frequencies for the full saved genre sample stay fixed when you search or filter games. Saved observations, not live or market-wide.</p></div>
 <details class="genre-raw-tags"><summary>All saved Steam tags <span>${tags.length} tags</span></summary><p>Unclassified source labels, including genres, styles and play modes. Counts are games with each tag, counted once per game.</p><div class="tags">${tags.length?tags.map(([tag,count])=>`<button class="tag ${params.tag===tag?'chosen':''}" data-tag="${e(tag)}" aria-pressed="${params.tag===tag}">${e(tag)} <small>${count}</small></button>`).join(''):'<span class="muted">No saved source tags.</span>'}</div></details></section>`;
}
function gamesPage(params,genre) {
 const selectedGenre=genre||params.genre;
 const list=selectGames(data.games,{...params,genre:selectedGenre,direction:params.sort==='name'?'asc':'desc'});
 return (genre?`<a href="#/overview" class="back">← Overview</a>`:'')+title(genre?'GENRE INTELLIGENCE':'DISCOVERY',genre||'Search',genre?'Explore player observations, game mechanics and the public marketing record.':'Find a genre, discover its games and compare source-backed observations.')+(!genre?genreSearch(params,true):'')+(selectedGenre?genreSummary(selectedGenre,params):'')+`<section class="panel games-panel" aria-label="Individual games">${controls(params,genre)}<div class="table-meta"><span><b>${list.length}</b> ${list.length===1?'game':'games'}${params.tag?' · Tag: '+e(params.tag):''}</span><span>Missing values sort last · Zero is a valid observation</span>${Object.values(params).some(Boolean)?'<button class="text-button" data-reset>Clear filters</button>':''}</div>${gameTable(list)}</section><p class="fineprint">Review counts use API purchase/language filters and are not interchangeable with localized store review summaries. Player counts are one-time observations, not current live values.</p>`;
}
function metricCard(metric,label){return `<div class="metric-card">${eyebrow(e(label))}<strong>${number(metric)}</strong><p>${e(metric.scope||'No observation available')}</p><div class="metric-meta">${pill(metric.freshness==='stale_cache'?'STALE CACHE':readable(metric.status||'observed'),hasValue(metric)&&metric.freshness!=='stale_cache'?'green':'neutral')}<span>${e(stamp(metric.observedAt))}</span></div>${link(metric.sourceUrl,metric.sourceLabel||'View original source')}${metric.refresh?`<small class="error-note">Latest bounded run: ${e(readable(metric.refresh.status))}. ${metric.refresh.status!=='accepted'?e(metric.refresh.reason)+' Older cached values retain their original timestamp; they do not enter this run’s score.':'Saved observation, not a live value.'}</small>`:''}${metric.error?`<small class="error-note">Collection note: ${e(metric.error)}</small>`:''}</div>`;}
function eventsMarkup(events){return events.length?`<ol class="timeline">${events.map(event=>`<li><div class="timeline-date">${e(date(event.date))}<small>${e(readable(event.dateKind))}</small></div><div class="timeline-content">${pill(readable(event.type))}<h3>${e(event.summary)}</h3>${link(event.url,'View evidence')}${event.discoveredOn?link(event.discoveredOn,'Discovery source'):''}</div></li>`).join('')}</ol>`:`<div class="empty compact"><h3>No detailed event records in this snapshot</h3><p>Absence of collected evidence does not mean absence of marketing activity.</p></div>`;}
function catalogPanel(g) {
 const c=g.catalog;
 if(c?.status!=='matched')return `<section class="panel catalog-panel catalog-empty" aria-labelledby="catalog-heading"><div class="catalog-heading"><div>${eyebrow('CATALOG CONTEXT')}<h2 id="catalog-heading">IGDB catalog</h2></div>${pill(c?.status==='not_imported'||!c?'NOT IMPORTED':readable(c.status),'neutral')}</div><p>${e(c?.reason||'No IGDB catalog artifact has been imported.')}</p><p class="catalog-note">The saved Steam identity, tags and observations remain available below. Unknown catalog fields are not filled in.</p></section>`;
 const names=values=>values.length?values.map(v=>e(v.name||'Unknown')).join(' · '):'<span class="muted">Not captured</span>';
 return `<section class="panel catalog-panel" aria-labelledby="catalog-heading"><div class="catalog-heading"><div>${eyebrow('CATALOG CONTEXT · IGDB')}<h2 id="catalog-heading">About this game<span class="accent">.</span></h2></div>${link(c.sourceUrl,'IGDB source','button secondary')}</div><p class="catalog-summary">${e(c.summary||'No summary was captured in this IGDB record.')}</p><div class="catalog-source-line">IGDB game ${e(c.sourceId)} · Exact Steam AppID crosswalk · Fetched ${e(stamp(c.fetchedAt))}</div><dl class="catalog-facts"><div><dt>Developer</dt><dd>${names(c.developers)}</dd></div><div><dt>Publisher</dt><dd>${names(c.publishers)}</dd></div><div><dt>Platforms · IGDB</dt><dd>${names(c.platforms)}</dd></div><div><dt>First recorded release · IGDB</dt><dd>${c.firstReleaseDate?e(date(c.firstReleaseDate)):'Not captured'}</dd></div><div><dt>Genres · IGDB</dt><dd>${names(c.genres)}</dd></div><div><dt>Themes · IGDB</dt><dd>${names(c.themes)}</dd></div><div class="catalog-wide"><dt>Keywords · IGDB</dt><dd>${names(c.keywords)}</dd></div><div class="catalog-wide"><dt>Official websites · IGDB label</dt><dd>${c.officialWebsites?.length?c.officialWebsites.map(site=>link(site.url,new URL(site.url).hostname)).join(' · '):'<span class="muted">Not captured</span>'}</dd></div></dl><p class="catalog-note">Catalog context only. Research genre: ${e(g.genre)}. Recurring mechanics and themes use saved Steam tags; IGDB labels do not enter those counts or Popularity Scores.</p><details class="catalog-details"><summary>Release records &amp; source comparison</summary><div class="catalog-source-line">Verified Steam name: ${e(g.steamName||g.name)} · Steam release display: ${e(g.releaseDate||'Not captured')} · ${link(g.storeUrl,'Steam source')}<br>IGDB provider update: ${e(stamp(c.sourceUpdatedAt))}. Fetch time is not the release date or an independent verification time.</div>${c.releaseDates.length?`<ul class="catalog-releases">${c.releaseDates.map(r=>`<li><b>${e(r.platform?.name||'Platform not captured')}</b><span>${e(r.displayDate||(r.date?date(r.date):'Date not captured'))}</span><small>${e([r.region?.region||'Region not captured',r.dateFormat?.format?`Precision: ${r.dateFormat.format}`:'Precision not captured',r.status?.name?`Status: ${r.status.name}`:'Release phase not captured'].join(' · '))}</small></li>`).join('')}</ul>`:'<p class="catalog-note">No platform-specific release records captured.</p>'}${c.conflicts.map(conflict=>`<p class="catalog-note"><b>${e(readable(conflict.status))}:</b> ${e(conflict.reason)}${conflict.field==='name'?` Steam: ${e(conflict.steam.value)}. IGDB: ${e(conflict.igdb.value)}.`:''}</p>`).join('')}<p class="catalog-note">Missing fields mean unknown, not confirmed absence. This saved record does not establish commercial reuse rights.</p></details></section>`;
}
function catalogMethods() {
 const c=data.meta.catalogIntegration;
 const total=data.games.length;
 const available=c?.matched||0;
 const fields=[['name','Name'],['summary','Summary'],['developers','Developer'],['publishers','Publisher'],['platforms','Platforms'],['releaseDates','Platform release records'],['genres','IGDB genres'],['themes','IGDB themes'],['keywords','IGDB keywords'],['officialWebsites','Official website · IGDB label']];
 return `<section class="panel definitions catalog-methods"><h2>IGDB catalog integration</h2><div><h3>${available} / ${total} games enriched</h3><p>${c?.status==='imported'?`Import run: ${e(readable(c.runStatus))}. ${c.unmatched} unmatched · ${c.ambiguous} ambiguous · ${c.quarantined} quarantined · ${c.unattempted} unattempted. These statuses are not zero-valued catalog observations.`:'No IGDB catalog artifact has been imported. The integration is ready for a bounded, verified import; existing Steam evidence remains the source.'}</p><p>IGDB fetch window: ${e(stamp(c?.fetchWindow?.start))}${c?.fetchWindow?.end&&c.fetchWindow.end!==c.fetchWindow.start?' – '+e(stamp(c.fetchWindow.end)):''}. Browser pages only read the saved snapshot; they never request live IGDB data.</p></div><div><h3>Source ownership stays explicit</h3><p>Accepted IGDB records supply catalog titles, summaries, company roles, platforms and provider taxonomies. Steam controls the Steam release display, concurrent players, review totals and recurring mechanic/theme tags. Editorial research genres and the score formula are unchanged. A catalog refresh never refreshes Steam observations.</p></div><div><h3>Identity before enrichment</h3><p>Only an exact Steam AppID from the verified Steam external-game source, a compatible name and a main-game record can attach. Saved Steam identity is checked again. Ambiguous, duplicate, shared-provider identities and parent/version records are quarantined; title similarity alone is never a join. The proposed identity-coverage target is 33 / 36. ${available>=33?'This import reaches that identity-coverage count.':'This import is below that target.'} Catalog coverage alone does not complete Milestone 1. Its scoped acceptance depends on separate source-validation checks; this private pilot does not establish production readiness.</p></div><div><h3>Conflicts, missingness and rights</h3><p>Both provider names and release records remain in the downloadable snapshot. Steam dates and cross-platform IGDB dates have different scopes; unknown region, precision or phase stays unknown. Empty fields mean not captured, not confirmed absence. Source attribution and fetch/provider-update times travel with accepted fields. Commercial use, retention and broader release permissions still need review.</p></div><div class="catalog-field-coverage" aria-label="IGDB field coverage">${fields.map(([key,label])=>`<div><span>${label}</span><b>${c?.fieldCoverage?.[key]||0} / ${total}</b></div>`).join('')}</div></section>`;
}
function gamePage(id){const g=data.games.find(g=>g.id===id);if(!g)return title('NOT FOUND','That game is not in this snapshot.','Return to the explorer to browse the tracked cohort.')+'<a href="#/search" class="button">Open explorer</a>';const m=g.marketing;return `<a href="#/search" class="back">← Game explorer</a>`+title(e(g.genre),g.name,`Steam release: ${g.releaseDate||'Not captured'} · ${g.cohort==='recent_6'?'Recent supplement':'Original pilot cohort'} · Steam app ${g.appid}`,link(g.storeUrl,'Open Steam page','button secondary'))+`${catalogPanel(g)}<div class="tags">${g.tags.map(t=>`<a class="tag" href="${route('search',{query:t})}">${e(t)}</a>`).join('')}</div><p class="fineprint">Visible store tags, including mechanics and themes. These are source labels, not model-validated classifications.</p><div class="metric-grid">${metricCard(g.players,'Concurrent players')}${metricCard(g.reviews,'API review total')}</div><section class="panel store-note"><div><h3>Localized store review summary</h3><p>${e(g.storeReviews.scope)}</p></div><div><strong>${number(g.storeReviews)}</strong>${link(g.storeReviews.sourceUrl,'Store source')}<small>${e(stamp(g.storeReviews.observedAt))}</small></div></section><section class="section-block"><div class="section-heading"><div>${eyebrow('THE PUBLIC RECORD')}<h2>Marketing evidence</h2></div>${pill(m.deepProof?'Deep evidence example':readable(m.status),m.deepProof?'green':'')}</div><div class="evidence-summary"><div><h3>${e(m.organization||'Organization not established')}</h3><p>${e(m.summary||'Not researched in this snapshot.')}</p><span class="muted">Source role: ${e(readable(m.sourceRole))}</span></div><div>${link(m.sourceUrl,'Profile source')}${link(m.associationUrl,'Identity / association source')}<small>Source status: ${e(readable(m.status))}</small></div></div>${eventsMarkup(m.events)}<div class="caveats"><h3>Interpretation notes</h3><ul>${m.caveats.map(c=>`<li>${e(c)}</li>`).join('')}</ul></div></section><div class="unknown-grid"><section><h3>Historical trend</h3><p>Not available. A single snapshot cannot establish growth, decline or how long a game was popular.</p></section><section><h3>Studio size & economics</h3><p>Unknown. No validated current headcount, sales estimate, marketing spend or causal ROI is provided.</p></section></div>${g.unknowns.length?`<details class="panel details"><summary>All data gaps for this game</summary><ul>${g.unknowns.map(t=>`<li>${e(readable(t))}</li>`).join('')}</ul></details>`:''}`;}
function marketingPage(params){const deep=data.games.filter(g=>g.marketing.deepProof);const types=[...new Set(deep.flatMap(g=>g.marketing.events.map(v=>v.type)))].sort();const category=params.category||'';const visible=deep.filter(g=>!category||g.marketing.events.some(v=>v.type===category));return title('BEHIND THE CAMPAIGNS','Marketing info','Public source profiles and a closer look at six games. Evidence of activity, not proof of effectiveness.')+`<div class="marketing-intro"><div>${eyebrow('SOURCE COVERAGE')}<strong>30<span> / 36</span></strong><p>games with a marketing profile</p></div><div><strong>6</strong><p>deep-evidence examples</p></div><div><strong>13</strong><p>discovered event records</p></div><div class="intro-note">A release announcement is a record.<br>A linked video is a lead.<br><b>Neither tells us what was spent.</b></div></div><div class="section-heading"><div>${eyebrow('FOLLOW THE SOURCES')}<h2>Six closer looks</h2></div><label class="select-wrap"><span>Record category</span><select data-filter="category" aria-label="Filter marketing category"><option value="">All record categories</option>${types.map(t=>`<option value="${e(t)}" ${t===category?'selected':''}>${e(readable(t))}</option>`).join('')}</select></label></div><div class="evidence-grid">${visible.map(g=>{const m=g.marketing;const events=m.events.filter(v=>!category||v.type===category);return `<article class="evidence-card"><div class="card-heading">${pill(g.genre)}<span>${events.length} ${events.length===1?'record':'records'}</span></div><h2><a href="${route('game/'+g.id)}">${e(g.name)} <span>→</span></a></h2><p class="organization">${e(m.organization)} · ${e(readable(m.sourceRole))}</p>${eventsMarkup(events)}<a class="text-link" href="${route('game/'+g.id)}">Full context & caveats →</a></article>`}).join('')}</div><div class="notice"><span class="notice-icon">i</span><div><b>Discovery is not a complete campaign history.</b><p>Undated sources stay undated. Featured creators are not assumed to be paid. Event records may include launches on platforms other than PC.</p></div></div><section class="panel source-status"><h2>Source accessibility across 30 profiles</h2><div>${Object.entries(data.meta.coverage.marketingStatuses).map(([s,n])=>`<span>${pill(readable(s))}<b>${n}</b></span>`).join('')}</div><a href="#/search">Browse all game profiles →</a></section>`;}
function steamMethods() {
 const m=data.meta.steamMetricsIntegration;
 const w=m?.fetchWindow||metricWindow();
 return `<section class="panel definitions steam-methods"><h2>Steam metric collection</h2><div><h3>Last collection window</h3><p>${e(windowText(w.start,w.end))}. ${m?.status==='imported'?`Run ${e(m.runId)} · ${e(readable(m.runStatus))}. ${m.accepted.players} / ${data.games.length} accepted current-player values; ${m.accepted.reviews} / ${data.games.length} accepted all-time review totals.`:'Preserved pilot observations; no later bounded Steam run has been imported.'}</p></div><div><h3>Fresh-run coverage and cached values</h3><p>${m?.status==='imported'?`${m.staleCache.players} older player counts and ${m.staleCache.reviews} older review totals remain visible as stale cache. Fetch failures, missing rows and rejected observations never become zero. Popularity Scores use only accepted CCU from this one run, normalized once across the complete accepted population. No older dates enter that baseline.`:'The saved pilot score uses its disclosed collection window. Unavailable observations never become zero.'} Scoring window: ${e(windowText(rankWindow().start,rankWindow().end))}. Retained numeric cache can make overall metric coverage larger than accepted run coverage.</p></div><div><h3>All-time review scope</h3><p>All-language, Steam-purchase, both positive and negative reviews; off-topic activity filtered. Only the exact verified Steam AppID and explicit all-time request filters can replace this metric. Date-window feasibility probes stay separate and cannot replace cumulative totals.</p></div><div><h3>Date-window review feasibility</h3><p>${m?.dateProbe?`${m.dateProbe.accepted} validated aggregate probe records; ${m.dateProbe.rejected} rejected or failed records. ${e(m.dateProbe.note)}`:'No later date-window aggregate probe artifact has been imported.'} These are endpoint feasibility observations, not a review history, player history or a validated trend. No review text or reviewer identities are included.</p>${m?.dateProbe?.failures?.length?`<ul>${m.dateProbe.failures.map(f=>`<li>Steam app ${e(f.appid)} · ${e(readable(f.purpose))}${f.httpStatus?` · HTTP ${e(f.httpStatus)}`:''}: ${e(f.reason)}</li>`).join('')}</ul>`:''}</div></section>`;
}
function steamDateMethods() {
 const m=data.meta.steamDateValidation;if(m?.status!=='imported')return '';
 return `<section class="panel definitions steam-date-methods"><h2>Latest date-window feasibility follow-up</h2><div><h3>Separate saved run</h3><p>${e(windowText(m.fetchWindow.start,m.fetchWindow.end))} · ${e(readable(m.runStatus))} · ${e(m.runId)}.</p><p>${e(m.note)} The earlier failed date request remains preserved in the current-metric run above.</p></div><div><h3>September 2026 bounded checks</h3><p>${m.completeEnumerations} / ${m.targetCount} complete matching-count enumerations; ${m.consistentPartitions} / ${m.targetCount} consistent partitions. Overall validation: ${e(readable(m.overallVerdict))}.</p><p>${m.checksPassed} / ${m.targetCount} targets passed enumeration, partition and exercised-boundary checks. ${m.emptyWindows} explicit empty windows had no boundary to exercise. ${m.inconclusive} other inconclusive targets · ${m.unattempted} not attempted. ${m.acceptedAggregateRequests} validated aggregate requests; ${m.rejectedAggregateRequests} rejected or failed requests.</p><ul>${m.probes.map(p=>`<li><b>${e(data.games.find(g=>g.appid===p.appid)?.name||'Steam app '+p.appid)}:</b> ${p.totalMatching===null?'No supported window count':p.totalMatching.toLocaleString('en-US')+' matching reviews'} · ${e(readable(p.status))}. Enumeration: ${p.completeEnumeration?'complete':'not established'}; partition: ${p.partitionMatches?'consistent':'not established'}; timestamp boundary: ${p.boundaryExercised?'exercised':'not exercised'}.</li>`).join('')}</ul><p>Period: 1–30 September 2026 UTC, inclusive. These endpoint checks are scoped to six selected games, with no market-wide or historical-trend claim.</p></div></section>`;
}
function coveragePage(){const c=data.meta.coverage;return title('DATA / SOURCES / METHODS','Know the source.','How observations become insights, and where the evidence ends.')+`<div class="status-banner"><span class="status-dot"></span><div><h2>Saved evidence. No live source requests.</h2><p>${e(steamStatusText())}</p></div>${pill('NOT LIVE','outline')}</div><section class="coverage-layout"><div class="panel coverage-card"><h2>What we have</h2><p class="muted">Coverage within the selected 36-game cohort</p>${[[36,'Verified game identities'],[c.currentPlayers,'Concurrent-player observations'],[c.reviewTotals,'API review totals'],[36,'Localized store review summaries'],[30,'Marketing source profiles'],[6,'Deep-evidence examples'],[data.meta.catalogIntegration?.matched||0,'IGDB catalog records']].map(([n,l])=>`<div class="coverage-row"><div><span>${l}</span><b>${n} / 36</b></div><div class="bar"><span style="width:${n/36*100}%"></span></div></div>`).join('')}</div><div class="panel coverage-card"><h2>What we can’t claim</h2><ul class="limits-list"><li><b>Market-wide rankings</b><span>This is an editorial cohort, not a representative sample of all Steam games.</span></li><li><b>Historical momentum</b><span>No time series, validated popularity score or hot-duration measure.</span></li><li><b>Commercial outcomes</b><span>No supported sales, revenue, spend, conversion or ROI estimates.</span></li><li><b>Team size</b><span>Credits and “indie” tags cannot establish a studio’s current headcount.</span></li><li><b>Mobile comparisons</b><span>Mobile data is not included in this pilot.</span></li></ul></div></section>${steamMethods()}${steamDateMethods()}${catalogMethods()}<section class="panel definitions"><h2>How the genre ranking works</h2>
<div><h3>Popularity Score · heuristic v${POPULARITY_SCORE_METHOD.version}</h3><p>A provisional 0–100 relative engagement proxy, built from concurrent-player observations. It is not calibrated market popularity, a percentile, a probability, market share or a sales estimate. A score of 100 means the strongest measured genre in this snapshot, not perfect or global popularity.</p></div>
<div><h3>70% median + 30% mean, on a log scale</h3><p class="score-formula">signal = 0.30 × ln(1 + mean) + 0.70 × ln(1 + median)<br>Popularity Score = 100 × signal ÷ max(signal across all rankable genres)</p><p>ln is the natural logarithm. The median has 70% weight to emphasize the typical observed game; the mean has 30% to retain some signal from hits. The logarithm compresses large values. These weights are a product choice, not empirically validated or fitted to outcomes; outlier influence is reduced, not eliminated.</p></div>
<div><h3>One global snapshot baseline</h3><p>The maximum uses every genre with supported observations in the complete snapshot, before any search, game filter or page selection. Scores display with one decimal place; ranking uses unrounded scores, highest first, with alphabetical ties. If every supported signal is zero, supported genres score 0.0; unknown genres remain unranked with a null score.</p></div>
<div><h3>Provisional · small sample</h3><p>${genreRanks.filter(row=>row.observedCount>0).length} genres have accepted player observations; the actual per-genre denominators are shown below. There is no uncertainty or sample-size adjustment. This editorial sample is not representative of the whole genre or Steam. Selection and missing coverage can materially change the ranking, so small score differences are not evidence of a reliable market advantage.</p></div>
<div><h3>Average players per observed game</h3><p>Average (arithmetic mean) = sum of supported concurrent-player observations in a genre ÷ number of games with supported observations in that genre. Raw mean, median and total remain visible below. The score combines the mean and median; it does not rank by raw total.</p></div>
<div><h3>Median alongside the mean</h3><p>The median is the middle player count after sorting supported observations. For an even number of games, it is the mean of the two middle values. Averaging does not eliminate outliers: Stardew Valley still strongly raises the farming mean. The median-weighted log blend reduces this influence without discarding it.</p></div>
<div><h3>Missing values never enter the denominator</h3><p>Only finite, non-negative numeric values marked observed, with a valid HTTP(S) source URL and parseable collection timestamp, are included. Each game belongs to one group and contributes once. A captured zero is included in both the mean and median. Unknown or unsupported counts are excluded from both the sum and the denominator. A genre without supported observations has no score; missing is never treated as zero. ${genreRanks.filter(row=>row.observedCount>0).length} genres have supported observations. A missing rank stays unavailable. ${data.meta.steamMetricsIntegration?.status==='imported'?'Only accepted CCU from the selected bounded run enters the score; older cached readings are excluded.':''}</p></div>
<div><h3>Future target: up to 100 games per genre</h3><p>A future comparison would select the top 100 eligible games in each genre by concurrent players at a comparable timestamp. If fewer than 100 eligible games have supported observations, use the actual number available as the denominator and disclose it. This snapshot does not yet contain that top-100 sample. Broader coverage may change both the ranking and its calibration.</p></div>
<div><h3>Relative scores are not a trend measure</h3><p>A genre’s score can change when the leading genre changes, even if its own player observations stay the same. Do not compare these normalized scores as a historical trend without a future fixed calibration. A single snapshot does not measure momentum or how long a game was popular.</p></div>
<div><h3>One collection window, not one instant</h3><p>Accepted scoring observations were captured sequentially during ${e(windowText(rankWindow().start,rankWindow().end))}. Means, medians, totals and scores combine those saved readings; they are not synchronized live counts, daily averages or unique players across the whole collection window.</p></div>
<div class="method-table"><table><thead><tr><th>Editorial genre</th><th class="numeric">Popularity Score<small>Provisional · / 100</small></th><th class="numeric">Average players / game</th><th class="numeric">Median players / game</th><th class="numeric">Observed total</th><th class="numeric">Games observed</th></tr></thead><tbody>${genreRanks.map(row=>`<tr><td>${e(row.genre)}</td><td class="numeric ${row.popularityScore===null?'missing':''}">${row.popularityScore===null?'Unranked':scoreNumber(row.popularityScore)+' / 100'}</td><td class="numeric ${row.average===null?'missing':''}">${row.average===null?'Not captured':summaryNumber(row.average)}</td><td class="numeric ${row.median===null?'missing':''}">${row.median===null?'Not captured':summaryNumber(row.median)}</td><td class="numeric ${row.total===null?'missing':''}">${row.total===null?'Not captured':row.total.toLocaleString('en-US')}</td><td class="numeric">${row.observedCount} / ${row.gameCount}</td></tr>`).join('')}</tbody></table></div></section><section class="panel definitions tag-methods"><h2>Recurring mechanics &amp; themes · tag heuristic v${GENRE_TAG_METHOD.version}</h2><div><h3>What these patterns mean</h3><p>These are recurring saved Steam source tags, not validated descriptions of actual game features. A conservative, explicit allowlist classifies a tag as a mechanic (an interaction or system) or theme (a setting or narrative subject). Unlisted tags are not classified. Exact labels remain unchanged; related tags are not merged or inferred.</p></div><div><h3>Frequency, coverage and ties</h3><p>Each exact tag is counted at most once per game. A recurring tag must appear in at least ${GENRE_TAG_METHOD.minimumGameCount} games. The combined top five mechanics and themes are ordered by game count, then alphabetically for ties. Percentage = games with that tag ÷ all games in the genre with at least one saved tag × 100. Games with only unclassified tags still enter that denominator. Untagged games are excluded, with coverage displayed. Fewer than five qualifying tags means fewer rows; no patterns are invented.</p></div><div><h3>Fixed whole-genre sample</h3><p>The Search genre selector and dedicated genre pages use the same complete saved genre sample. Game queries, cohort filters, sorting and tag clicks change only the individual game list. They never recompute the displayed genre metrics, global score baseline or recurring-tag frequencies. Tag coverage is independent of concurrent-player coverage, so an unranked genre can still have supported tag patterns.</p></div><div><h3>What the classifier leaves out</h3><p>Generic genre labels, play modes, visual styles, perspectives, difficulty, subjective quality, input devices and release labels are excluded. For example, Indie, Singleplayer, Multiplayer, Casual, Difficult, Puzzle, RPG, Strategy, Pixel Graphics and Early Access are not mechanics or themes in this heuristic. This conservative selection can miss relevant concepts. All saved source labels remain available on game pages and in the genre’s raw-tag filters.</p></div><div><h3>Mechanic tag allowlist</h3><p class="tag-rule-list">${GENRE_TAG_METHOD.mechanicTags.map(e).join(' · ')}</p></div><div><h3>Theme tag allowlist</h3><p class="tag-rule-list">${GENRE_TAG_METHOD.themeTags.map(e).join(' · ')}</p></div></section><section class="panel definitions"><h2>Reading the numbers</h2><div><h3>Concurrent players</h3><p>Steam-connected players at the observation time. Not owners, daily active users, sales, daily averages or all-time peaks.</p></div><div><h3>API review total</h3><p>All-language, all-time Steam-purchase reviews with off-topic activity filtered. Not interchangeable with the localized store summary shown separately on game pages.</p></div><div><h3>Missing is not zero</h3><p>“Not captured” means no supported numeric value was saved. An observed zero is displayed as 0. Missing values always sort last.</p></div><div><h3>Marketing records</h3><p>Non-exhaustive discovered evidence. Event date, publication date and collection time are distinct. Source accessibility is not permission for bulk collection or redistribution.</p></div></section><section class="panel provenance"><h2>Snapshot provenance</h2><dl><dt>Saved Steam / marketing evidence began</dt><dd>${e(stamp(data.meta.collectionWindow.start))}</dd><dt>Saved Steam / marketing evidence ended</dt><dd>${e(stamp(data.meta.collectionWindow.end))}</dd><dt>Last Steam metric collection</dt><dd>${e(windowText(data.meta.steamMetricsIntegration?.fetchWindow?.start||metricWindow().start,data.meta.steamMetricsIntegration?.fetchWindow?.end||metricWindow().end))}</dd><dt>Saved Steam tags</dt><dd>${e(windowText(data.meta.tagCollectionWindow?.start,data.meta.tagCollectionWindow?.end))}</dd><dt>Snapshot built</dt><dd>${e(stamp(data.meta.builtAt))}</dd><dt>Scope</dt><dd>30 original games + 6-game recent supplement</dd><dt>Runtime</dt><dd>Local static files. No accounts, analytics or live source requests.</dd></dl><p class="fineprint">Independent research prototype; not affiliated with or endorsed by Valve, Steam, IGDB, or Twitch. ${link('https://partner.steamgames.com/doc/webapi_overview','Steam Web API source')} · ${link('https://api-docs.igdb.com/','IGDB API source')}</p><a class="button secondary" href="/data/snapshot.json" download="fieldnote-snapshot.json">Download source-linked snapshot ↓</a> <a class="button secondary" href="/docs/roadmap.docx" download="game-market-research-roadmap.docx">Download project roadmap ↓</a></section>`;}
function render({focusInput=null,selection=null}={}){const {path,params}=state();const rawPage=path[0]||'overview';const page=rawPage==='games'?'search':rawPage==='coverage'?'methods':rawPage;let content;try{content=page==='overview'?overview(params):page==='search'?gamesPage(params):page==='genre'?gamesPage(params,decodeURIComponent(path.slice(1).join('/'))):page==='game'?gamePage(path[1]):page==='marketing'?marketingPage(params):page==='methods'?coveragePage():title('NOT FOUND','This page isn’t in the workspace.','Use the navigation to return to your research.');}catch(err){console.error(err);content=title('DISPLAY ERROR','We couldn’t open this view.','Try returning to the overview.');}app.innerHTML=shell(['game','genre'].includes(page)?'search':page,content);document.title=`${page==='game'?data.games.find(g=>g.id===path[1])?.name||'Game':({overview:'Overview',search:'Search',genre:'Genre intelligence',marketing:'Marketing info',methods:'Data, sources & methods'})[page]||'Research'} · Fieldnote`;if(focusInput){const input=document.getElementById(focusInput);input?.focus({preventScroll:true});if(selection!==null&&input)input.setSelectionRange(selection.start,selection.end);}}
function updateFilter(key,value){const inputId=key==='genreQuery'?'genre-search':key==='query'?'search':null;const input=inputId?document.getElementById(inputId):null;const selection=input?{start:input.selectionStart,end:input.selectionEnd}:null;const {path,params}=state();if(value)params[key]=value;else delete params[key];history.replaceState(null,'',route(path.join('/'),params));render({focusInput:inputId,selection});if(!inputId)document.querySelector(`[data-filter="${key}"]`)?.focus();}
app.addEventListener('input',ev=>{if(ev.target.id==='search')updateFilter('query',ev.target.value);if(ev.target.id==='genre-search')updateFilter('genreQuery',ev.target.value);});
app.addEventListener('submit',ev=>{if(ev.target.id!=='genre-form')return;ev.preventDefault();const query=document.getElementById('genre-search').value.trim();const matches=data.genres.filter(g=>g.toLowerCase().includes(query.toLowerCase()));const exact=data.genres.find(g=>g.toLowerCase()===query.toLowerCase());if(exact||matches.length===1)location.hash=route('genre/'+encodeURIComponent(exact||matches[0]));else if(state().path[0]==='overview')location.hash=route('search',{genreQuery:query});else document.querySelector('.genre-results a')?.focus();});
app.addEventListener('change',ev=>{if(ev.target.dataset.filter)updateFilter(ev.target.dataset.filter,ev.target.value)});
app.addEventListener('click',ev=>{const reset=ev.target.closest('[data-reset]');if(reset){const{path}=state();history.replaceState(null,'',route(path.join('/')));render();}if(ev.target.closest('[data-clear-genre]'))updateFilter('genreQuery','');const tag=ev.target.closest('[data-tag]');if(tag){const value=tag.dataset.tag;const recurring=tag.classList.contains('trait-button');const rawOpen=document.querySelector('.genre-raw-tags')?.open;updateFilter('tag',state().params.tag===value?'':value);const rawTags=document.querySelector('.genre-raw-tags');if(rawTags&&rawOpen)rawTags.open=true;[...document.querySelectorAll(recurring?'.trait-button':'.genre-raw-tags [data-tag]')].find(button=>button.dataset.tag===value)?.focus({preventScroll:true});}});
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);document.querySelector('#main')?.focus({preventScroll:true});});
window.addEventListener('keydown',ev=>{const preferredSearch=document.querySelector('#search')||document.querySelector('#genre-search');if(ev.key==='/'&&!['INPUT','SELECT','TEXTAREA'].includes(document.activeElement.tagName)&&preferredSearch){ev.preventDefault();preferredSearch.focus();}if(ev.key==='Escape'&&document.activeElement.id==='search')updateFilter('query','');if(ev.key==='Escape'&&document.activeElement.id==='genre-search')updateFilter('genreQuery','');});
try{const response=await fetch('/data/snapshot.json');if(!response.ok)throw new Error('Snapshot not found');data=await response.json();genreRanks=rankGenres(data.games,data.genres);render();}catch(err){app.innerHTML=`<main class="load-error"><h1>Snapshot unavailable</h1><p>The local research snapshot could not be opened. Run npm run snapshot, then reload this page.</p><button onclick="location.reload()">Try again</button></main>`;console.error(err);}
